import{z as B,x as s,o as r,c as p,q as A,j as i,D as e,d as t,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"EUV 底层","description":"","frontmatter":{"title":"EUV 底层","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-underlayer.md","filePath":"litho/euv-underlayer.md","lastUpdated":1791413859000}'),d={name:"litho/euv-underlayer.md"};function h(u,a,C,m,D,c){const l=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=A('<h1 id="euv-底层" tabindex="-1">EUV 底层 <a class="header-anchor" href="#euv-底层" aria-label="Permalink to &quot;EUV 底层&quot;">​</a></h1><div class="epigraph"><p>胶不是直接坐在器件膜上成像的。底层决定黏附、二次电子、出气隔离和刻蚀预算；换胶化学而不换底层，等于只换了记录介质的上半截。</p><footer>—— 据 Levinson 对底层 / 抗反射层的产线讨论，以及公开的 EUV 底层功能划分整理</footer></div><p><a href="/litho/tin-oxide-resist">上一课</a>（锡氧胶化学）。把记录介质分到 CAR 与金属氧化物两条工作点。缺口不是再选一次 PAG 或锡氧笼，而是薄膜下面那一层：EUV 胶往往只有十几纳米量级，黏附、衬底毒化、二次电子和硬掩模预算都压在 underlayer 上。本课钉底层功能。界面的二次电子怎么改灵敏度与模糊，留给<a href="/litho/euv-secondary-electron">下一课</a>；接触孔的随机缺失，是后面<a href="/litho/stochastic-holes">随机缺陷与缺失孔</a>一课的良率墙。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DUV 的 BARC 首先是为驻波与衬底反射服务的。<a href="/litho/resist-contrast-curve">衬度曲线</a>已经警告过：无 BARC 时 \\(T(E)\\) 会振荡。EUV 的 13.5 nm 在大多数叠层上反射弱，驻波不再是第一理由。薄胶却把另一组问题抬上来：旋涂膜在疏水或金属表面上掉、CAR 被衬底碱或金属离子淬灭出 footing、出气打到多层膜、显影后的浮雕扛不住干法。</p><p>金属氧化物胶更薄、自身可当硬掩模，但仍要平面化、黏附和二次电子管理。缺口因此是「胶种选定之后，栈怎么接」，不是重讲 RLS 三角。</p><h3 id="底层不是把-duv-barc-涂薄一点" tabindex="-1">底层不是把 DUV BARC 涂薄一点 <a class="header-anchor" href="#底层不是把-duv-barc-涂薄一点" aria-label="Permalink to &quot;底层不是把 DUV BARC 涂薄一点&quot;">​</a></h3><p>EUV 底层常见功能叠在同一膜或两层栈上：黏附与浸润、平面化、二次电子产额、出气阻挡、刻蚀选择比、阻挡衬底对酸的毒化。公开讨论里它可以是旋涂碳、含硅、含金属的有机无机杂化，而不是「抗反射涂料换波长」。把 KrF BARC 配方直接减厚，会在黏附和二次电子上同时失手。</p><p><span class="marginnote">二次电子可以从底层射进胶，等效增加吸收事件。这能抬灵敏度，也会把界面附近的模糊和随机一起改写。底层不是光学上的透明垫片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选底层要和上一课的胶种绑死。CAR：优先防 footing、控酸在界面的淬灭/反射，并给有机胶一个够用的刻蚀硬掩模。金属氧化物：优先黏附、平面化、以及显影液不钻蚀界面；硬掩模功能部分由胶自身承担，底层改管图形转移的下一段。换胶批次等于换底层模型，OPC 紧凑抗蚀剂模块要重校准，不能只改剂量。</p><p><span class="marginnote">把胶栈想成三明治：最薄的「馅」是记录图形的光刻胶，下面的底层兼任面包和餐盘——既要让馅粘得住（黏附），又要隔热隔味（化学隔离、出气阻挡），吃完整顿还不能在桌上留渣（颗粒与沾污）。换馅不换面包，味道和端相都会变。</span></p><p>涂布在轨道上完成：膜厚、烘烤、与胶的层间混合窗口都是工艺旋钮。过烘会改变二次电子产额与应力；欠烘则溶剂残留、黏附垮。本课不把轨道食谱写成唯一表，只要求窗口实验声明底层。</p><h3 id="与空中像的接口" tabindex="-1">与空中像的接口 <a class="header-anchor" href="#与空中像的接口" aria-label="Permalink to &quot;与空中像的接口&quot;">​</a></h3><p>底层改的是界面处的有效剂量与黏附，不改物镜 TCC。但界面二次电子会给潜像加一个轴向不对称的模糊，侧壁和清底剂量跟着走。E–D 窗若在换底层后搬家，先查界面而不是先怪照明。</p>',15)),(r(),i(n,null,{default:e(()=>[o(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20AIR%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20UL%5B%22EUV%20%E5%BA%95%E5%B1%82%3A%20%E9%BB%8F%E9%99%84%20%2F%20%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%20%2F%20%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20CAR%5B%22CAR%22%5D%20--%3E%20UL%0A%20%20MOR%5B%22%E9%87%91%E5%B1%9E%E6%B0%A7%E5%8C%96%E7%89%A9%E8%83%B6%22%5D%20--%3E%20UL%0A%20%20UL%20--%3E%20LAT%5B%22%E6%BD%9C%E5%83%8F%E4%B8%8E%E6%B8%85%E5%BA%95%22%5D%0A%20%20UL%20--%3E%20ET%5B%22%E5%88%BB%E8%9A%80%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"EUV 光子在胶里吸收长度短，相当一部分能量停在膜下半与界面。底层若含较高原子序数，局部二次电子产额上升，靠近界面的脱保护或交联被加强——灵敏度看起来「免费」提高，其实是把事件统计从胶体挪到界面。CAR 的酸若被衬底淬灭，底部溶解变慢，孔清不干净；底层把胶与衬底隔开，是化学隔离，不是光学隔离。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"CAR 的 footing 就是孔底被「腌」得溶解变慢，剖面上像长了外八字的小裙边，严重时孔根本清不开。根因常是衬底中的碱或金属离子淬灭了界面附近的酸——所以第一反应是换底层做隔离，而不是无脑加剂量。")],-1)),a[6]||(a[6]=E("p",null,"刻蚀端，薄 CAR 几乎必须靠底层当硬掩模；金属氧化物胶把选择比买在自身骨架上，底层更多是黏附与平坦。两种胶的失败模式不同：前者是转印时胶先没，后者是涂布缺陷和金属沾污。Levinson 把底层放进工艺栈而不是镜头规格，原因在此。",-1)),(r(),i(n,null,{default:e(()=>[o(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAR%5B%22CAR%20%E8%96%84%E8%83%B6%22%5D%20--%3E%20HM%5B%22%E5%BA%95%E5%B1%82%E5%85%BC%E4%BB%BB%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20HM%20--%3E%20F1%5B%22%E5%85%B8%E5%9E%8B%E5%A4%B1%E8%B4%A5%3A%20%E8%BD%AC%E5%8D%B0%E6%97%B6%E8%83%B6%E5%85%88%E8%80%97%E5%B0%BD%22%5D%0A%20%20MOR%5B%22%E9%87%91%E5%B1%9E%E6%B0%A7%E5%8C%96%E7%89%A9%E8%83%B6%22%5D%20--%3E%20SELF%5B%22%E8%83%B6%E8%87%AA%E8%BA%AB%E9%AA%A8%E6%9E%B6%E5%BD%93%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20SELF%20--%3E%20F2%5B%22%E5%85%B8%E5%9E%8B%E5%A4%B1%E8%B4%A5%3A%20%E6%B6%82%E5%B8%83%E7%BC%BA%E9%99%B7%E4%B8%8E%E9%87%91%E5%B1%9E%E6%B2%BE%E6%B1%A1%22%5D%0A%20%20SE%5B%22%E7%95%8C%E9%9D%A2%E4%BA%8C%E6%AC%A1%E7%94%B5%E5%AD%90%22%5D%20--%3E%20BOTH%5B%22%E4%B8%A4%E7%A7%8D%E8%83%B6%E7%9A%84%E7%81%B5%E6%95%8F%E5%BA%A6%E4%B8%8E%E6%A8%A1%E7%B3%8A%E9%83%BD%E8%A2%AB%E6%94%B9%E5%86%99%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p>这张图回答的是：两种胶栈的分工与失败模式差在哪——底层在 CAR 里是承重的硬掩模，在金属氧化物栈里退为配角，失败方式随之换位。</p><h3 id="出气与沾污是栈的合同" tabindex="-1">出气与沾污是栈的合同 <a class="header-anchor" href="#出气与沾污是栈的合同" aria-label="Permalink to &quot;出气与沾污是栈的合同&quot;">​</a></h3><p>EUV 真空里，胶与底层的出气会打到多层膜。底层可以当阻挡，也可以自己成为出气源。金属底层还要过腔体沾污门。实验室里好看的 LER，若底层颗粒或针孔把缺孔密度抬起来，产线不会收。合同是缺陷密度与镜头污染，不是底层折射率表。</p><p><span class="marginnote">报 EUV 胶数据必须写底层：材料族、厚度、烘烤。只报「某金属胶更敏」而省略 underlayer，和只报模型 loss 不报数据预处理是同一类误导。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某供应商的底层牌号写成节点标准，也不把 DUV BARC 的光学厚度公式搬来算 EUV。驻波课的抗反射设计在这里降为次要项，但高反射衬底（某些金属）仍可能要单独处理，不能说「EUV 永不需要抗反射」。</p><p><span class="marginnote">初学者容易只比较「哪种胶更灵敏」。同一支胶换个底层，剂量与侧壁就能差出可观幅度；只报「某胶 \\(E_0\\) 更低」而隐去底层材料、厚度与烘烤，这组数据几乎无法横向比较——对比之前先对齐栈。</span></p><p>后课默认：说到 EUV 胶，栈包含底层；换胶或换底层都要重做剂量、黏附和随机尾部。缺孔统计如何成为良率墙，后面的随机缺孔课才展开，不在这里用平均 CD 代替。</p><p><span class="marginnote">平面化失败会把局部焦面抬成底层厚度图。看起来像扫描机调平，根子在旋涂。先量底层均匀性，再拧工件台。</span></p><p>后课需要的定义到此为止：underlayer 是功能栈，不是 BARC 的别名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 底层接在 CAR / 金属氧化物胶之后，管黏附、二次电子、隔离与刻蚀预算。</li><li>驻波不再是第一理由；把 DUV BARC 减厚当 EUV 底层会失手。</li><li>换胶必须换底层模型；界面二次电子会改灵敏度与模糊。</li><li>合同是缺陷、出气与沾污，不是折射率。</li><li>二次电子产额是下一课；随机缺孔随后。</li><li>出处：Levinson, <em>Principles of Lithography</em>；公开的 EUV 底层功能讨论。</li></ul>',12))])}const U=B(d,[["render",h]]);export{V as __pageData,U as default};
